public String getDOT(DFA dfa, boolean isLexer) {
    if (dfa.s0 == null) return null;

    ST dot = stlib.getInstanceOf("dfa");
    dot.add("name", "DFA" + dfa.decision);
    dot.add("startState", dfa.s0.stateNumber);
    dot.add("rankdir", rankdir);

    for (DFAState d : dfa.states.keySet()) {
        if (d.isAcceptState || d.stateNumber == Integer.MAX_VALUE) {
            addState(dot, d);
        }
    }

    for (DFAState d : dfa.states.keySet()) {
        if (d.edges != null) {
            for (int i = 0; i < d.edges.length; i++) {
                addEdge(dot, d, d.edges[i], i, isLexer);
            }
        }
    }

    String output = dot.render();
    return Utils.sortLinesInString(output);
}

private void addState(ST dot, DFAState d) {
    ST st = stlib.getInstanceOf(d.isAcceptState ? "stopstate" : "state");
    st.add("name", "s" + d.stateNumber);
    st.add("label", getStateLabel(d));
    dot.add("states", st);
}

private void addEdge(ST dot, DFAState d, DFAState target, int i, boolean isLexer) {
    if (target == null || target.stateNumber == Integer.MAX_VALUE) return;

    int ttype = i - 1; // we shift up for EOF as -1 for parser
    String label = isLexer ? "\'" + getEdgeLabel(String.valueOf((char) i)) + "\'" :
                              (grammar != null ? grammar.getTokenDisplayName(ttype) : String.valueOf(ttype));

    ST st = stlib.getInstanceOf("edge");
    st.add("label", label);
    st.add("src", "s" + d.stateNumber);
    st.add("target", "s" + target.stateNumber);
    st.add("arrowhead", arrowhead);
    dot.add("edges", st);
}

public String getDOT(DFA dfa, boolean isLexer) {
    if (dfa.s0 == null) return null;

    ST dot = stlib.getInstanceOf("dfa");
    dot.add("name", "DFA" + dfa.decision);
    dot.add("startState", dfa.s0.stateNumber);
    dot.add("rankdir", rankdir);

    for (DFAState d : dfa.states.keySet()) {
        if (d.isAcceptState || d.stateNumber == Integer.MAX_VALUE) {
            ST st = stlib.getInstanceOf("stopstate");
            st.add("name", "s" + d.stateNumber);
            st.add("label", getStateLabel(d));
            dot.add("states", st);
        } else {
            ST st = stlib.getInstanceOf("state");
            st.add("name", "s" + d.stateNumber);
            st.add("label", getStateLabel(d));
            dot.add("states", st);
        }

        if (d.edges != null) {
            for (int i = 0; i < d.edges.length; i++) {
                DFAState target = d.edges[i];
                if (target != null && target.stateNumber != Integer.MAX_VALUE) {
                    int ttype = i - 1; // shift up for EOF as -1 for parser
                    String label = isLexer ? "\'" + getEdgeLabel(String.valueOf((char) i)) + "\'" : (grammar != null ? grammar.getTokenDisplayName(ttype) : String.valueOf(ttype));
                    ST st = stlib.getInstanceOf("edge");
                    st.add("label", label);
                    st.add("src", "s" + d.stateNumber);
                    st.add("target", "s" + target.stateNumber);
                    st.add("arrowhead", arrowhead);
                    dot.add("edges", st);
                }
            }
        }
    }

    String output = dot.render();
    return Utils.sortLinesInString(output);
}

public String getDOT(DFA dfa, boolean isLexer) {
