        } else if (t.getClass() == WildcardTransition.class) {
            look.addAll(IntervalSet.of(Token.MIN_USER_TOKEN_TYPE, atn.maxTokenType));
        } else {
            IntervalSet set = t.label();
            if (set != null) {
