protected void _LOOK(@NotNull ATNState state, @Nullable PredictionContext context,
                     @NotNull IntervalSet lookaheadSet, @NotNull Set<ATNConfig> busySet,
                     boolean seeThroughPredicates, boolean includeEOF) {

    ATNConfig config = new ATNConfig(state, 0, context);
    if (!busySet.add(config)) return;

    if (state instanceof RuleStopState) {
        handleRuleStopState(context, lookaheadSet, includeEOF, state);
        return;
    }

    processTransitions(state, context, lookaheadSet, busySet, seeThroughPredicates, includeEOF);
}

private void handleRuleStopState(@Nullable PredictionContext context, @NotNull IntervalSet lookaheadSet, 
                                  boolean includeEOF, @NotNull ATNState state) {
    if (context == null) {
        lookaheadSet.add(Token.EPSILON);
    } else if (context.isEmpty() && includeEOF) {
        lookaheadSet.add(Token.EOF);
    } else if (context != PredictionContext.EMPTY) {
        for (SingletonPredictionContext parentContext : context) {
            ATNState returnState = atn.states.get(parentContext.returnState);
            _LOOK(returnState, parentContext.parent, lookaheadSet, lookBusy, seeThroughPredicates, includeEOF);
        }
    }
}

private void processTransitions(@NotNull ATNState state, @Nullable PredictionContext context, 
                                @NotNull IntervalSet lookaheadSet, @NotNull Set<ATNConfig> busySet, 
                                boolean seeThroughPredicates, boolean includeEOF) {
    int transitionCount = state.getNumberOfTransitions();
    for (int i = 0; i < transitionCount; i++) {
        Transition transition = state.transition(i);
        if (transition instanceof RuleTransition) {
            PredictionContext newContext = SingletonPredictionContext.create(context, 
                ((RuleTransition) transition).followState.stateNumber);
            _LOOK(transition.target, newContext, lookaheadSet, busySet, seeThroughPredicates, includeEOF);
        } else if (transition instanceof PredicateTransition) {
            if (seeThroughPredicates) {
                _LOOK(transition.target, context, lookaheadSet, busySet, seeThroughPredicates, includeEOF);
            } else {
                lookaheadSet.add(HIT_PRED);
            }
        } else if (transition.isEpsilon()) {
            _LOOK(transition.target, context, lookaheadSet, busySet, seeThroughPredicates, includeEOF);
        } else if (transition instanceof WildcardTransition) {
            lookaheadSet.addAll(IntervalSet.of(Token.MIN_USER_TOKEN_TYPE, atn.maxTokenType));
        } else {
            processLabel(transition, lookaheadSet);
        }
    }
}

private void processLabel(@NotNull Transition transition, @NotNull IntervalSet lookaheadSet) {
    IntervalSet labelSet = transition.label();
    if (labelSet != null) {
        if (transition instanceof NotSetTransition) {
            labelSet = labelSet.complement(IntervalSet.of(Token.MIN_USER_TOKEN_TYPE, atn.maxTokenType));
        }
        lookaheadSet.addAll(labelSet);
    }
}

