public String getDOT(DFA dfa, boolean isLexer) {
    if (dfa.s0 == null) return null;

    ST dot = stlib.getInstanceOf("dfa");
    dot.add("name", "DFA" + dfa.decision);
    dot.add("startState", dfa.s0.stateNumber);
    dot.add("rankdir", rankdir);

    addAcceptStates(dot, dfa);
    addNonAcceptStates(dot, dfa, isLexer);

    String output = dot.render();
    return Utils.sortLinesInString(output);
}

private void addAcceptStates(ST dot, DFA dfa) {
    for (DFAState state : dfa.states.keySet()) {
        if (state.isAcceptState) {
            ST acceptStateTemplate = stlib.getInstanceOf("stopstate");
            acceptStateTemplate.add("name", "s" + state.stateNumber);
            acceptStateTemplate.add("label", getStateLabel(state));
            dot.add("states", acceptStateTemplate);
        }
    }
}

private void addNonAcceptStates(ST dot, DFA dfa, boolean isLexer) {
    for (DFAState state : dfa.states.keySet()) {
        if (!state.isAcceptState && state.stateNumber != Integer.MAX_VALUE) {
            ST nonAcceptStateTemplate = stlib.getInstanceOf("state");
            nonAcceptStateTemplate.add("name", "s" + state.stateNumber);
            nonAcceptStateTemplate.add("label", getStateLabel(state));
            dot.add("states", nonAcceptStateTemplate);
            addEdges(dot, state, isLexer);
        }
    }
}

private void addEdges(ST dot, DFAState state, boolean isLexer) {
    if (state.edges != null) {
        for (int i = 0; i < state.edges.length; i++) {
            DFAState target = state.edges[i];
            if (target != null && target.stateNumber != Integer.MAX_VALUE) {
                int ttype = i - 1; // we shift up for EOF as -1 for parser
                String label = isLexer ? "\'" + getEdgeLabel(String.valueOf((char) i)) + "\'" : grammar.getTokenDisplayName(ttype);
                ST edgeTemplate = stlib.getInstanceOf("edge");
                edgeTemplate.add("label", label);
                edgeTemplate.add("src", "s" + state.stateNumber);
                edgeTemplate.add("target", "s" + target.stateNumber);
                edgeTemplate.add("arrowhead", arrowhead);
                dot.add("edges", edgeTemplate);
            }
        }
    }
}

