protected ATNConfigSet computeReachSet(ATNConfigSet closure, int t, boolean fullCtx) {
    if (debug) System.out.println("in computeReachSet, starting closure: " + closure);

    if (mergeCache == null) {
        mergeCache = new DoubleKeyMap<PredictionContext, PredictionContext, PredictionContext>();
    }

    ATNConfigSet intermediate = new ATNConfigSet(fullCtx);
    List<ATNConfig> skippedStopStates = new ArrayList<ATNConfig>();

    for (ATNConfig c : closure) {
        if (debug) System.out.println("testing " + getTokenName(t) + " at " + c.toString());

        if (c.state instanceof RuleStopState) {
            assert c.context.isEmpty();
            if (fullCtx || t == IntStream.EOF) {
                skippedStopStates.add(c);
            }
            continue;
        }

        for (int ti = 0; ti < c.state.getNumberOfTransitions(); ti++) {
            Transition trans = c.state.transition(ti);
            ATNState target = getReachableTarget(trans, t);
            if (target != null) {
                intermediate.add(new ATNConfig(c, target), mergeCache);
            }
        }
    }

    ATNConfigSet reach = null;

    if (skippedStopStates.isEmpty()) {
        if (intermediate.size() == 1 || getUniqueAlt(intermediate) != ATN.INVALID_ALT_NUMBER) {
            reach = intermediate;
        }
    }

    if (reach == null) {
        reach = new ATNConfigSet(fullCtx);
        Set<ATNConfig> closureBusy = new HashSet<ATNConfig>();
        for (ATNConfig c : intermediate) {
            closure(c, reach, closureBusy, false, fullCtx);
        }
    }

    if (t == IntStream.EOF) {
        reach = removeAllConfigsNotInRuleStopState(reach, reach == intermediate);
    }

    if (!skippedStopStates.isEmpty() && (!fullCtx || !PredictionMode.hasConfigInRuleStopState(reach))) {
        for (ATNConfig c : skippedStopStates) {
            reach.add(c, mergeCache);
        }
    }

    return reach.isEmpty() ? null : reach;
}
